"""Rules for C8 (memory/RAG), C11 (adversarial robustness) and C12 (monitoring & logging)."""
from .base import E, V, S, CODE_ONLY

RULES = [
    # ------------------------------------------------------------------ C8
    V("AIS-RAG-001", "Vector database client without authentication or TLS", "5.2.1 8.1.3", S.MEDIUM,
      callee=r"\bchromadb\.(?:HttpClient|AsyncHttpClient)|\bQdrantClient|\bweaviate\.(?:connect_to_local|Client|connect_to_custom)|\bMilvusClient|\bconnections\.connect|\bnew\s+ChromaClient|\bnew\s+QdrantClient",
      missing_any=r"api_key|apiKey|auth|token|headers|credentials|user\s*=|password|ssl|https|secure|:memory:|\bpath\s*=|location\s*=",
      langs=frozenset(CODE_ONLY), max_hits_per_file=3, confidence="medium",
      message="Vector store connection has no credentials/TLS configured",
      remediation="Enable authentication (API key/mTLS), TLS, and per-collection access control with default-deny."),
    V("AIS-RAG-002", "Retrieval query without authorization / tenant scope filter", "5.2.2 8.1.3 8.1.1", S.MEDIUM,
      callee=r"\.(?:similarity_search(?:_with_score|_by_vector)?|as_retriever|query_points|vector_search|max_marginal_relevance_search|get_relevant_documents)\b",
      missing_any=r"filter|where|namespace|tenant|metadata|search_kwargs|\bacl\b|user_id|owner|partition|scope|with_filter|query_filter|\bmust\b|kwargs",
      requires=("rag",), langs=frozenset(CODE_ONLY | {"notebook"}), max_hits_per_file=3, confidence="low",
      message="Retrieval is executed with no visible user/tenant scope; any user may retrieve any indexed chunk",
      remediation="Apply the end-user's authorization context (metadata filter/namespace/ACL) at every retrieval and assembly stage."),
    V("AIS-RAG-003", "Chroma/vector DB reset or anonymous access enabled", "5.2.1 8.3.2", S.MEDIUM,
      pattern=r"allow_reset\s*[=:]\s*[\"']?(?:true|True)|ALLOW_RESET\s*[=:]\s*[\"']?(?:true|TRUE)|AUTHENTICATION_ANONYMOUS_ACCESS_ENABLED\s*[=:]\s*[\"']?(?:true|TRUE)|anonymous_access\s*[=:]\s*(?:true|True)",
      message="Unauthenticated or destructive endpoints exposed on the vector store",
      remediation="Disable anonymous access and remote reset; require auth for all operations."),
    E("AIS-EV-EMBED-REDACT", "PII/secret detection before embedding", "8.2.1 1.2.3",
      requires=("rag", "training"),
      pattern=r"presidio|AnalyzerEngine|AnonymizerEngine|\bscrubadub\b|\bpiiranha\b|mask_pii|detect_secrets|trufflehog|gitleaks|pii[_ ]?(?:filter|detect|redact|scrub)|redact\w*\(|anonymi[sz]e\w*\(|comprehend[\s\S]{0,60}pii|dlp_v2|tokeniz\w*_pii"),
    E("AIS-EV-MEM-EXPIRY", "Memory/vector expiry (TTL)", "8.3.1",
      requires=("rag", "agent"),
      pattern=r"\bttl\b|expires?_at|\bexpiry\b|time_to_live|valid_until|expire_after|\bexpires?\b\s*[=:]"),
    E("AIS-EV-MEM-RESET", "Memory reset / deletion capability", "8.3.2 8.3.3",
      requires=("rag", "agent"),
      pattern=r"delete_collection|\.reset\(\)|clear_memory|reset_memory|\bforget\b|\bpurge\b|\.delete\(\s*(?:ids|where|filter)|memory\.clear\(|delete_index|\bquarantine\b"),
    E("AIS-EV-DOC-TAG", "Documents tagged at write time (source, writer, timestamp)", "12.5.4 8.1.2",
      requires=("rag",),
      pattern=r"metadata\s*=\s*\{[^}]{0,300}(?:source|author|owner|writer|created_by|uploaded_by)[^}]{0,300}(?:timestamp|created_at|ingested_at|date|time)|metadata\s*=\s*\{[^}]{0,300}(?:timestamp|created_at|ingested_at)[^}]{0,300}(?:source|author|owner|writer|created_by|uploaded_by)",
      confidence="medium"),
    E("AIS-EV-VECTOR-ANOMALY", "Vector/content anomaly detection & quarantine before indexing", "8.2.2 8.2.4 8.2.5",
      requires=("rag",),
      pattern=r"IsolationForest|LocalOutlierFactor|\bpyod\b|outlier|\bquarantine\b|retrieval[_ ]poison|rag[_ ]poison|poison\w*[_ ]detect|contradiction[_ ]detect|conflict[_ ]detect", confidence="low"),
    E("AIS-EV-MEM-WRITE-VALIDATION", "Validated writes to trusted agent memory", "8.2.3",
      requires=("rag", "agent"),
      pattern=r"validate[_ ]memory|memory[_ ]write[_ ]policy|trusted[_ ]memory|source[_ ]validation|provenance[_ ]check|untrusted[_ ]memory", confidence="low"),

    # ------------------------------------------------------------------ C11
    E("AIS-EV-ADV-EVAL", "Adversarial attack evaluation tooling", "11.1.3",
      pattern=r"adversarial-robustness-toolbox|\bart\.attacks|\bfoolbox\b|\bcleverhans\b|\btextattack\b|\badvertorch\b|\bautoattack\b|\brobustbench\b|\bgarak\b|\bpyrit\b|\bpromptfoo\b|\bPromptBench\b|\bharmbench\b|\badvbench\b|llm-attacks|\bgiskard\b|\bdeepteam\b|\bjailbreakbench\b|\bagentdojo\b|red[_ -]?team"),
    E("AIS-EV-ADV-HARDEN", "Adversarial hardening", "11.1.4",
      pattern=r"adversarial[_ ]training|AdversarialTrainer|\bPGD\b|\bFGSM\b|\bTRADES\b|randomized[_ ]smoothing|certified[_ ]robust|defensive[_ ]distillation|input[_ ]transformation|art\.defences|safety[_ ]fine[_ -]?tun|\bRLHF\b|\bDPOTrainer\b|constitutional[_ ]ai|circuit[_ ]breakers?", confidence="medium"),
    E("AIS-EV-ALIGNMENT-TRAIN", "Alignment / safety training or fine-tuning", "11.1.1",
      pattern=r"safety[_ ]fine[_ -]?tun|\bRLHF\b|\bDPOTrainer\b|\bPPOTrainer\b|constitutional[_ ]ai|safety[_ ]alignment|refusal[_ ]training|\bRLAIF\b|llama[_ -]?guard|alignment[_ ]dataset", confidence="low"),
    E("AIS-EV-HARM-RATE", "Automated harmful-content rate + regression threshold", "11.1.5",
      pattern=r"harmful[_ -]rate|attack[_ ]success[_ ]rate|\bASR\b[^\n]{0,40}(?:threshold|<|>)|safety_score|toxicity_rate|harm_rate|regression[^\n]{0,40}threshold|llm[_ -]judge", confidence="low"),
    E("AIS-EV-CLEAN-VS-ADV", "Adversarial results reported with clean baseline", "11.1.6",
      pattern=r"clean[_ ]accuracy|robust[_ ]accuracy|benign[_ ]accuracy|no[_ ]attack|attack[_ ]free|baseline[^\n]{0,40}adversarial|adversarial[^\n]{0,40}baseline", confidence="low"),
    E("AIS-EV-RATELIMIT", "Per-principal / global rate limiting on inference endpoints", "11.2.2",
      pattern=r"\bslowapi\b|\bLimiter\(|RateLimiter|rate_limit|ratelimit|rate-limit|express-rate-limit|rateLimit\(|\bthrottl\w+|limit_req\b|limit_req_zone|upstash/ratelimit|flask_limiter|django-ratelimit|@limiter|token[_-]bucket|TokenBucket|bucket4j|usage_plan|api_throttl|rate-limiting"),
    E("AIS-EV-EXTRACTION-DETECT", "Query-pattern / extraction-attempt detection", "11.3.1 12.2.4",
      pattern=r"extraction[_ -]?(?:detect|attempt|attack|alert)|query[_ -]pattern|model[_ -]extraction|suspicious[_ ]queries|abuse[_ ]detect|bot[_ ]detect|fraud_score|similar[_ ]queries", confidence="low"),
    E("AIS-EV-EXTRACTION-RESPONSE", "Response measures on suspected extraction", "11.3.4",
      pattern=r"block_user|ban_user|suspend_(?:user|key)|revoke_(?:key|api_key)|throttle_user|disable_key|quarantine_user", confidence="low"),
    E("AIS-EV-DP", "Differentially-private optimization", "11.2.4",
      requires=("training",),
      pattern=r"\bopacus\b|\bPrivacyEngine\b|tensorflow_privacy|\bDPKerasSGD|\bdiffprivlib\b|dp_sgd|\bDPOptimizer\b|make_private|jax_privacy|dp-accounting|differential[_ ]privacy|noise_multiplier|\bDP-?SGD\b"),
    E("AIS-EV-MIA-TEST", "Membership-inference attack simulation", "11.2.5",
      requires=("training", "model_loading"),
      pattern=r"privacy_meter|membership[_ -]inference|MembershipInference|privacy_tests|\bmia_attack\b|\bLiRA\b"),
    E("AIS-EV-CALIBRATION", "Output confidence calibration", "11.2.3",
      pattern=r"CalibratedClassifierCV|temperature[_ ]scaling|\bisotonic\b|\bplatt\b|\bcalibrat(?:e|ion|or)\b|expected_calibration_error|\bECE\b|label_smoothing", confidence="low"),
    E("AIS-EV-WATERMARK-MODEL", "Model watermarking / fingerprinting", "11.3.3",
      pattern=r"model[_ ]watermark|watermark[_ ]model|model[_ ]fingerprint|\bsynthid\b|kirchenbauer|\bMarkLLM\b|\bllm[_ -]watermark|green[_ ]list", confidence="medium"),
    E("AIS-EV-ANOMALY-INPUT", "Anomaly / OOD detection on inputs", "11.4.1 11.4.2",
      pattern=r"IsolationForest|LocalOutlierFactor|OneClassSVM|alibi[_-]?detect|\bpyod\b|Mahalanobis|outlier[_ -]?detect|anomaly[_ -]?detect|out[_-]of[_-]distribution|\bOOD\b|novelty[_ ]detect|perplexity[_ ]filter|anomaly[_ ]score", confidence="medium"),
    E("AIS-EV-FEEDBACK-GATE", "Poisoning detection / human review in safety feedback pipeline", "11.4.3",
      pattern=r"feedback[^\n]{0,60}(?:review|moderat|poison|approv)|(?:review|moderat|approv)[^\n]{0,60}feedback", confidence="low"),

    # ------------------------------------------------------------------ C12
    E("AIS-EV-OBSERVABILITY", "AI interaction logging / tracing", "12.1.1",
      requires=("llm",),
      pattern=r"\blangfuse\b|\blangsmith\b|LANGCHAIN_TRACING|\bopentelemetry\b|\bopenllmetry\b|\btraceloop\b|\barize\b|phoenix\.otel|\bopeninference\b|\bhelicone\b|mlflow\.(?:tracing|openai|langchain)|weave\.init|\bbraintrust\b|\blunary\b|\bportkey\b|LLMObs|\bpromptlayer\b|\bhoneyhive\b|\blogfire\b|\bagentops\b|\bliteralai\b|\bopik\b|logger\.\w+\([^)]*(?:prompt|completion|messages|response)"),
    E("AIS-EV-GENAI-SCHEMA", "Structured GenAI telemetry schema (OTel gen_ai)", "12.1.3 12.1.1",
      requires=("llm",),
      pattern=r"gen_ai\.(?:request\.model|usage\.input_tokens|usage\.output_tokens|system|provider\.name|operation\.name)|GenAIAttributes|SpanAttributes\.LLM_|openinference\.semconv|llm\.token_count|OTEL_SEMCONV_STABILITY_OPT_IN|opentelemetry-instrumentation-(?:openai|anthropic|langchain|bedrock|vertexai)|\b(?:OpenAI|Anthropic|LangChain)Instrumentor"),
    E("AIS-EV-SAFETY-LOG", "Safety/policy decisions logged", "12.1.2",
      requires=("llm",),
      pattern=r"log\w*\.\w+\([^)]*(?:moderation|flagged|blocked|policy|guardrail|safety|violation|categories|injection)", confidence="low"),
    E("AIS-EV-RAG-LOG", "Retrieval events logged", "12.1.4",
      requires=("rag",),
      pattern=r"on_retriever_end|on_retriever_start|retriever[_ ]span|log\w*\.\w+\([^)]*(?:retriev|documents|sources|chunks|doc_ids)|span_kind[^\n]{0,20}RETRIEVER|\blangfuse\b|LangfuseCallback|\btraceloop\b|\bopeninference\b", confidence="low"),
    E("AIS-EV-ALERTING", "Alerting / SIEM integration", "12.2.1 12.2.3",
      pattern=r"sentry_sdk|\bpagerduty\b|\bopsgenie\b|alertmanager|send_alert|raise_alert|notify_security|\bsiem\b|\bsplunk\b|\bwazuh\b|\bfalco\b|PutMetricAlarm|\bsigma\b|\byara\b|detection[_-]?rules?", confidence="low"),
    E("AIS-EV-BEHAVIOR-ANOMALY", "Behavioral anomaly detection on conversations", "12.2.2",
      pattern=r"excessive[_ ]retr(?:y|ies)|probing|behavio(?:u)?ral[_ ]anomal|retry[_ ]count|conversation[_ ]anomal|session[_ ]anomal", confidence="low"),
    E("AIS-EV-TOKEN-USAGE", "Granular token-usage attribution", "12.2.5",
      requires=("llm",),
      pattern=r"usage\.(?:total_tokens|prompt_tokens|completion_tokens|input_tokens|output_tokens)|token_usage|usage_metadata|get_openai_callback|cost_tracking|track_usage|UsageLimits|litellm\.completion_cost|tokens_used|response_metadata|\bopenmeter\b|\blago\b|virtual_keys?|team_budget|per[-_]user[-_](?:quota|budget)"),
    E("AIS-EV-C2-MONITOR", "LLM API covert-channel / C2 traffic monitoring", "12.2.6",
      pattern=r"covert[_ -]channel|\bC2\b[^\n]{0,30}(?:detect|monitor)|egress[_ ]monitor|llm[_ ]gateway|ai[_ ]gateway|api[_ ]gateway[^\n]{0,40}llm", confidence="low"),
    E("AIS-EV-DRIFT", "Data/model drift detection", "12.3.1 12.3.4",
      requires=("llm", "model_loading", "training"),
      pattern=r"\bevidently\b|alibi[_-]?detect|\bnannyml\b|\bwhylogs\b|ks_2samp|kolmogorov|population[_ ]stability|\bPSI\b|(?:data|concept|embedding)[_ ]drift|drift[_ ]detect|DataDriftPreset|\bKSDrift|\bMMDDrift|river\.drift|\bADWIN\b|\bfiddler\b|\baporia\b|\bdeepchecks\b"),
    E("AIS-EV-HALLUCINATION", "Hallucination detection / groundedness evaluation", "12.3.2 7.2.1",
      requires=("llm",),
      pattern=r"selfcheckgpt|hallucination[_ ]?(?:detect|score|rate|metric|guard)|HallucinationMetric|\bHHEM\b|groundedness|faithfulness|\btrulens\b|\bragas\b|answer[_ ]relevancy|context[_ ]precision"),
    E("AIS-EV-HALLUCINATION-METRIC", "Hallucination rate tracked as time series", "12.3.3",
      requires=("llm",),
      pattern=r"(?:Gauge|Histogram|Counter|Summary)\([^)]*halluc|halluc\w*[_ ]rate|hallucination_rate", confidence="medium"),
    E("AIS-EV-PROACTIVE-ANALYSIS", "Security evaluation on autonomous action triggers", "12.4.1",
      requires=("agent",),
      pattern=r"threat[_ ]landscape|proactive[_ ]security|behavior[_ ]pattern[_ ]analysis|pre[_-]?action[_ ]check|security[_ ]evaluation[^\n]{0,40}trigger", confidence="low"),
    E("AIS-EV-AUDIT-PROACTIVE", "Audit logs for security-critical actions (approver, timestamp, params, outcome)", "12.4.2",
      requires=("agent",),
      pattern=r"audit[_ ]log\w*[^\n]{0,120}(?:approver|approved_by)|(?:approver|approved_by)[^\n]{0,120}audit|audit_trail", confidence="low"),
    E("AIS-EV-KILLSWITCH-LOG", "Kill-switch/override activations logged", "12.4.3",
      pattern=r"kill[_-]?switch[^\n]{0,80}\blog\w*|\blog\w*[^\n]{0,80}kill[_-]?switch|override[^\n]{0,60}audit", confidence="low"),
    E("AIS-EV-IMMUTABLE-AUDIT", "Immutable audit records for model changes", "12.5.3",
      pattern=r"object[_ ]lock|ObjectLock|\bWORM\b|append[_-]only|\bimmudb\b|\brekor\b|\bledger\b|\bQLDB\b|retention_mode|CloudTrail|immutable[_ ]log", confidence="low"),
    E("AIS-EV-LABEL-AUDIT", "Labeling activity audit logging", "12.5.2",
      requires=("training",),
      pattern=r"label[_ ]?(?:audit|log|history)|annotation[_ ]?(?:audit|log|history)|annotator[_ ]activity", confidence="low"),
]
